pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(uint256 drugs, address sender) public {
        vm.assume(drugs > 0);
        vm.assume(sender != address(0));
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.seedMarket{value: 0}(drugs);
        assertTrue(c.initialized());
    }
}
